import os
import platform
import re
import shutil
import sys
import sysconfig
import zipfile
import kt

INDEX = "https://pypi.org/pypi"
SITE = sysconfig.get_paths()["purelib"]
BIN = "/usr/bin"
DATA = sys.prefix
TMP = "/tmp/pip"
ME = "kt-pip"
PY = sys.version_info[:2]
PLATS = ("musllinux_1_2_i686", "musllinux_1_1_i686")

HELP = """usage: pip install [-U] [--no-deps] [-r файл] [-i url] пакет...
       pip uninstall [-y] пакет...
       pip list | freeze | show пакет
  install    установка колёс (wheel) с PyPI через браузер вместе с зависимостями
  -U         обновить до последней версии
  --no-deps  без зависимостей
  -r файл    пакеты из requirements.txt
  -i url     адрес JSON API (по умолчанию %s)
  uninstall  удаление пакета, поставленного этим pip
  list       установленные пакеты
  freeze     установленные пакеты в формате requirements.txt
  show       версия, зависимости и файлы пакета

Подходят колёса py3-none-any и musllinux i686 для CPython %d.%d. Если колеса нет
или PyPI недоступен, пакет ставится из репозитория kt (kt pkg add python-...).
Исходники (sdist) не собираются.""" % (INDEX, PY[0], PY[1])

FETCH = """async (url) => {
  let r;
  try { r = await fetch(url); }
  catch { throw new Error("нет ответа от " + new URL(url).host + " (сеть или CORS)"); }
  if (r.status === 404) return null;
  if (!r.ok) throw new Error(new URL(url).host + ": " + r.status);
  const j = await r.json(), out = {};
  for (const [v, all] of Object.entries(j.releases || {})) {
    const files = all.filter((f) => !f.yanked);
    if (!files.length) continue;
    const ok = files.filter((f) => /-none-any\\.whl$/.test(f.filename) || /musllinux_[0-9_]+_i686/.test(f.filename));
    out[v] = [ok.map((f) => [f.filename, f.url, f.requires_python || "", f.size || 0]), files.some((f) => f.filename.endsWith(".whl"))];
  }
  return { name: j.info.name, releases: out };
}"""

REPO = """async () => {
  const base = String(kt.cfg["pkg.repo"] || "/repo").replace(/\\/+$/, "");
  try { const r = await fetch(base + "/pypi.txt"); return r.ok ? await r.text() : ""; } catch { return ""; }
}"""

ENV = {
    "python_version": "%d.%d" % PY,
    "python_full_version": platform.python_version(),
    "implementation_version": platform.python_version(),
    "os_name": "posix",
    "sys_platform": "linux",
    "platform_system": "Linux",
    "platform_machine": "i686",
    "platform_python_implementation": "CPython",
    "implementation_name": "cpython",
    "platform_release": "",
    "platform_version": "",
}

VER = re.compile(r"^v?(?:(\d+)!)?(\d+(?:\.\d+)*)(?:[-_.]?(a|b|c|rc|alpha|beta|pre|preview)[-_.]?(\d*))?"
                 r"(?:-(\d+)|[-_.]?(post|rev|r)[-_.]?(\d*))?(?:[-_.]?(dev)[-_.]?(\d*))?(?:\+[a-z0-9._]*)?$")
PRE = {"a": 0, "alpha": 0, "b": 1, "beta": 1, "c": 2, "rc": 2, "pre": 2, "preview": 2}


class Fail(Exception):
    pass


def say(s):
    if not QUIET:
        print(s, flush=True)


def norm(name):
    return re.sub(r"[-_.]+", "-", name).lower()


def vparse(v):
    m = VER.match(v.strip().lower())
    if not m:
        return None
    rel = [int(x) for x in m.group(2).split(".")]
    while len(rel) > 1 and rel[-1] == 0:
        rel.pop()
    pre = (PRE[m.group(3)], int(m.group(4) or 0)) if m.group(3) else None
    post = m.group(5) or (m.group(7) or "0" if m.group(6) else None)
    dev = int(m.group(9) or 0) if m.group(8) else None
    pk = pre if pre else (-1, 0) if dev is not None and post is None else (9, 0)
    return (int(m.group(1) or 0), tuple(rel), pk, int(post) if post is not None else -1, dev if dev is not None else 1 << 30)


def release(v):
    m = VER.match(v.strip().lower())
    return [int(x) for x in m.group(2).split(".")] if m else []


def is_pre(v):
    k = vparse(v)
    return k is not None and (k[2][0] < 9 or k[4] != 1 << 30)


def prefix(v, p):
    a, b = release(v), [int(x) for x in p.split(".") if x.isdigit()]
    a += [0] * (len(b) - len(a))
    return a[:len(b)] == b


def match(v, spec):
    for part in spec.split(","):
        part = part.strip().strip("()").strip()
        if not part:
            continue
        m = re.match(r"(===|==|!=|~=|>=|<=|>|<)\s*(.+)$", part)
        if not m:
            raise Fail("не понял условие версии: " + part)
        op, sv = m.group(1), m.group(2).strip()
        if op == "===":
            ok = v == sv
        elif op in ("==", "!=") and sv.endswith(".*"):
            ok = prefix(v, sv[:-2]) == (op == "==")
        else:
            a, b = vparse(v), vparse(sv)
            if a is None or b is None:
                return False
            if op == "==":
                ok = a == b
            elif op == "!=":
                ok = a != b
            elif op == ">=":
                ok = a >= b
            elif op == "<=":
                ok = a <= b
            elif op == ">":
                ok = a > b
            elif op == "<":
                ok = a < b
            else:
                ok = a >= b and prefix(v, ".".join(str(x) for x in release(sv)[:-1]))
        if not ok:
            return False
    return True


def marker(text, extras):
    toks = re.findall(r"""\s*(\(|\)|"[^"]*"|'[^']*'|===|==|!=|~=|>=|<=|<|>|not\s+in\b|in\b|and\b|or\b|[A-Za-z_][A-Za-z0-9_.]*)""", text)
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def take():
        pos[0] += 1
        return toks[pos[0] - 1]

    def value():
        t = take()
        if t[0] in "\"'":
            return ("s", t[1:-1])
        return ("v", t)

    def compare():
        if peek() == "(":
            take()
            r = expr()
            take()
            return r
        a, op, b = value(), re.sub(r"\s+", " ", take()), value()
        if "extra" in (a[1] if a[0] == "v" else "", b[1] if b[0] == "v" else ""):
            lit = b[1] if a[0] == "v" else a[1]
            return (norm(lit) in extras) == (op == "==")
        x = ENV.get(a[1], "") if a[0] == "v" else a[1]
        y = ENV.get(b[1], "") if b[0] == "v" else b[1]
        if op == "in":
            return x in y
        if op == "not in":
            return x not in y
        if vparse(x) is not None and vparse(y) is not None:
            return match(x, op + y)
        return (x == y) if op in ("==", "===") else (x != y) if op == "!=" else False

    def conj():
        r = compare()
        while peek() == "and":
            take()
            r = compare() and r
        return r

    def expr():
        r = conj()
        while peek() == "or":
            take()
            r = conj() or r
        return r

    try:
        return expr()
    except (IndexError, TypeError):
        raise Fail("не понял маркер: " + text)


def requirement(text):
    text = text.split(" #", 1)[0].strip()
    m = re.match(r"^([A-Za-z0-9][A-Za-z0-9._-]*)\s*(?:\[([^\]]*)\])?\s*([^;@]*)(@[^;]*)?(?:;(.*))?$", text)
    if not m:
        raise Fail("не понял требование: " + text)
    if m.group(4):
        raise Fail("установка по ссылке не поддерживается: " + text)
    extras = {norm(e) for e in (m.group(2) or "").split(",") if e.strip()}
    return m.group(1), extras, m.group(3).strip().strip("()").strip(), (m.group(5) or "").strip()


def tags(filename):
    parts = filename[:-4].split("-")
    if len(parts) < 5:
        return None
    return parts[-3].split("."), parts[-2].split("."), parts[-1].split(".")


def score(filename):
    t = tags(filename)
    if not t:
        return None
    best = None
    for py in t[0]:
        for abi in t[1]:
            for plat in t[2]:
                if plat == "any":
                    ps = 2
                elif plat in PLATS:
                    ps = 0
                else:
                    continue
                m = re.match(r"^(py|cp)(\d)(\d*)$", py)
                if not m or int(m.group(2)) != PY[0] or (m.group(3) and int(m.group(3)) > PY[1]):
                    continue
                if abi == "none":
                    s = ps + 2
                elif abi == "abi3" and m.group(1) == "cp":
                    s = ps + 1
                elif abi == "cp%d%d" % PY and py == "cp%d%d" % PY:
                    s = ps
                else:
                    continue
                best = s if best is None else min(best, s)
    return best


class Pip:
    def __init__(self, index, upgrade, deps):
        self.index = index.rstrip("/")
        self.upgrade = upgrade
        self.deps = deps
        self.projects = {}
        self.installed = installed()
        self.map = None

    def repo(self):
        if self.map is None:
            self.map = repo_map()
        return self.map

    def project(self, name):
        key = norm(name)
        if key not in self.projects:
            try:
                self.projects[key] = kt.js(FETCH, "%s/%s/json" % (self.index, key), timeout=120)
            except kt.JSError as e:
                raise Fail(str(e))
            except OSError as e:
                raise Fail(str(e))
        p = self.projects[key]
        if p is None:
            raise Fail("%s: нет на PyPI" % name)
        return p

    def choose(self, name, spec):
        p = self.project(name)
        vers = [v for v in p["releases"] if vparse(v) is not None and match(v, spec)]
        vers.sort(key=vparse, reverse=True)
        final = [v for v in vers if not is_pre(v)]
        allow_pre = any(is_pre(re.sub(r"^[=<>!~]+", "", s.strip())) for s in spec.split(",") if s.strip())
        sdist_only = None
        for v in (vers if allow_pre or not final else final):
            files, wheels = p["releases"][v]
            good = []
            for f in files:
                if not f[0].endswith(".whl"):
                    continue
                s = score(f[0])
                if s is None or (f[2] and not match(platform.python_version(), f[2])):
                    continue
                good.append((s, f))
            if good:
                good.sort(key=lambda x: x[0])
                return p["name"], v, good[0][1]
            if sdist_only is None:
                sdist_only = (v, not wheels)
        if not vers:
            raise Fail("%s: нет версии под условие %s" % (name, spec or "(любая)"))
        if sdist_only and sdist_only[1]:
            raise Fail("%s %s: только исходники (sdist), сборка здесь не поддерживается" % (p["name"], sdist_only[0]))
        raise Fail("%s: нет колеса для CPython %d.%d i686 musl (нужно py3-none-any или musllinux_i686)" % (p["name"], PY[0], PY[1]))

    def download(self, url, filename, size):
        dest = TMP + "/" + filename
        if os.path.exists(dest) and (not size or os.path.getsize(dest) == size):
            return dest
        say("скачиваю %s (%d КБ)" % (filename, (size + 1023) // 1024))
        d = "%s/in.%s.d" % (kt.RUN, kt._rid())
        os.makedirs(d)
        try:
            paths, err = kt._upload("fetch", kt._b64(url), d)
            got = os.listdir(d)
            if not got:
                raise Fail("%s: %s" % (filename, err or "не скачалось"))
            shutil.move(d + "/" + got[0], dest)
        finally:
            shutil.rmtree(d, ignore_errors=True)
        return dest

    def resolve(self, reqs):
        plan = {}
        specs = {}
        top = {norm(r[0]) for r in reqs}
        queue = list(reqs)
        while queue:
            name, extras, spec, mark = queue.pop(0)
            if mark and not marker(mark, extras):
                continue
            key = norm(name)
            specs.setdefault(key, [])
            if spec:
                specs[key].append(spec)
            need = ",".join(specs[key])
            if key in plan:
                if match(plan[key]["version"], need) and extras <= plan[key]["extras"]:
                    continue
                extras = extras | plan[key]["extras"]
            have = self.installed.get(key)
            if have and key not in plan and match(have["version"], need) and not (self.upgrade and key in top):
                if extras and self.deps:
                    for r in have["requires"]:
                        n, e, s, mk = requirement(r)
                        if mk and marker(mk, extras) and not marker(mk, set()):
                            queue.append((n, e, s, mk))
                continue
            if have and not have["ours"]:
                if match(have["version"], need):
                    continue
                raise Fail("%s %s установлен системой (kt pkg), а нужно %s" % (have["name"], have["version"], need))
            r = self.repo().get(key)
            try:
                if r and r["shim"]:
                    raise Fail("")
                real, ver, f = self.choose(name, need)
            except Fail as e:
                if not r:
                    raise Fail("%s; в репозитории kt тоже нет" % e)
                if not match(r["version"], need):
                    raise Fail("%s%sв репозитории kt %s %s, а нужно %s" % (e, "; " if str(e) else "", r["pkg"], r["version"], need))
                plan[key] = {"name": r["name"], "version": r["version"], "kt": r["pkg"], "extras": extras, "top": key in top}
                continue
            if have and have["version"] == ver:
                continue
            path = self.download(f[1], f[0], f[3])
            meta = wheel_meta(path)
            plan[key] = {"name": real, "version": ver, "path": path, "extras": extras, "top": key in top}
            if self.deps:
                for r in meta["requires"]:
                    n, e, s, mk = requirement(r)
                    if not mk or marker(mk, extras):
                        queue.append((n, e, s, ""))
        return plan

    def install(self, reqs):
        os.makedirs(TMP, exist_ok=True)
        plan = self.resolve(reqs)
        if not plan:
            say("всё уже установлено")
            return
        done = []
        kts = sorted({p["kt"] for p in plan.values() if p.get("kt")})
        if kts:
            say("из репозитория kt: " + " ".join(kts))
            if os.system("kt pkg add -y %s%s" % ("-q " if QUIET else "", " ".join(kts))) != 0:
                raise Fail("kt pkg add не справился")
            done += ["%s-%s" % (p["name"], p["version"]) for p in plan.values() if p.get("kt")]
        for key, p in plan.items():
            if p.get("kt"):
                continue
            old = self.installed.get(key)
            if old:
                remove(old)
            install_wheel(p["path"], p["top"])
            done.append("%s-%s" % (p["name"], p["version"]))
            os.remove(p["path"])
        say("установлено: " + " ".join(done))


def repo_map():
    out = {}
    try:
        text = kt.js(REPO, timeout=60) or ""
    except (kt.JSError, OSError):
        text = ""
    for line in text.split("\n"):
        f = line.split("\t")
        if len(f) >= 3 and f[0]:
            out[norm(f[0])] = {"name": f[0], "version": f[1], "pkg": f[2], "shim": f[1].endswith("+kt")}
    return out


def read_meta(path):
    out = {"requires": []}
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            for line in f:
                if not line.strip():
                    break
                k, _, v = line.partition(":")
                v = v.strip()
                if k == "Name":
                    out["name"] = v
                elif k == "Version":
                    out["version"] = v
                elif k == "Summary":
                    out["summary"] = v
                elif k == "Requires-Dist":
                    out["requires"].append(v)
    except OSError:
        pass
    return out


def wheel_meta(path):
    with zipfile.ZipFile(path) as z:
        for n in z.namelist():
            if n.count("/") == 1 and n.endswith(".dist-info/METADATA"):
                tmp = TMP + "/METADATA"
                with open(tmp, "wb") as f:
                    f.write(z.read(n))
                m = read_meta(tmp)
                os.remove(tmp)
                return m
    raise Fail("%s: в колесе нет METADATA" % os.path.basename(path))


def installed():
    out = {}
    try:
        names = os.listdir(SITE)
    except OSError:
        return out
    for d in names:
        if d.endswith(".dist-info"):
            meta = SITE + "/" + d + "/METADATA"
        elif d.endswith(".egg-info"):
            meta = SITE + "/" + d + ("/PKG-INFO" if os.path.isdir(SITE + "/" + d) else "")
        else:
            continue
        m = read_meta(meta)
        if "name" not in m:
            continue
        try:
            with open(SITE + "/" + d + "/INSTALLER") as f:
                who = f.read().strip()
        except OSError:
            who = ""
        m.update(dir=SITE + "/" + d, ours=who == ME, system=who != ME)
        m.setdefault("version", "0")
        out[norm(m["name"])] = m
    return out


def place(target, data, mode=None):
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, "wb") as f:
        f.write(data)
    if mode:
        os.chmod(target, mode)


def install_wheel(path, requested):
    files = []
    with zipfile.ZipFile(path) as z:
        names = z.namelist()
        info = next(n.split("/")[0] for n in names if n.count("/") == 1 and n.endswith(".dist-info/METADATA"))
        data = info[:-len(".dist-info")] + ".data/"
        for n in names:
            if n.endswith("/"):
                continue
            body = z.read(n)
            if n.startswith(data):
                kind, _, rest = n[len(data):].partition("/")
                if kind in ("purelib", "platlib"):
                    target = SITE + "/" + rest
                elif kind == "scripts":
                    target = BIN + "/" + os.path.basename(rest)
                    if re.match(rb"#!(?:\S*env\s+)?\S*python", body) and b"\n" in body:
                        body = b"#!" + sys.executable.encode() + body[body.index(b"\n"):]
                    place(target, body, 0o755)
                    files.append(target)
                    continue
                elif kind == "headers":
                    target = sysconfig.get_paths()["include"] + "/" + rest
                else:
                    target = DATA + "/" + rest
            else:
                target = SITE + "/" + n
            if n == info + "/RECORD":
                continue
            place(target, body, 0o755 if (z.getinfo(n).external_attr >> 16) & 0o111 else None)
            files.append(target)
    ep = SITE + "/" + info + "/entry_points.txt"
    if os.path.exists(ep):
        section = None
        with open(ep) as f:
            for line in f:
                line = line.strip()
                if line.startswith("["):
                    section = line.strip("[]")
                elif section in ("console_scripts", "gui_scripts") and "=" in line:
                    cmd, _, ref = line.partition("=")
                    mod, _, attr = ref.strip().split(" ")[0].partition(":")
                    head = attr.split(".")[0]
                    target = BIN + "/" + cmd.strip()
                    place(target, ("#!%s\nimport sys\nfrom %s import %s\nif __name__ == \"__main__\":\n    sys.exit(%s())\n"
                                   % (sys.executable, mod.strip(), head, attr)).encode(), 0o755)
                    files.append(target)
    place(SITE + "/" + info + "/INSTALLER", (ME + "\n").encode())
    if requested:
        place(SITE + "/" + info + "/REQUESTED", b"")
    files += [SITE + "/" + info + "/INSTALLER", SITE + "/" + info + "/RECORD"] + ([SITE + "/" + info + "/REQUESTED"] if requested else [])
    place(SITE + "/" + info + "/RECORD", "".join(
        "%s,,\n" % (os.path.relpath(f, SITE) if f.startswith(SITE + "/") else f) for f in files).encode())


def remove(dist):
    paths = []
    try:
        with open(dist["dir"] + "/RECORD") as f:
            for line in f:
                p = line.rsplit(",", 2)[0].strip().strip('"')
                if p:
                    paths.append(p if p.startswith("/") else os.path.normpath(SITE + "/" + p))
    except OSError:
        raise Fail("%s: нет RECORD, не знаю, какие файлы удалять" % dist["name"])
    dirs = set()
    for p in paths:
        if p.endswith(".py"):
            cache = os.path.dirname(p) + "/__pycache__"
            stem = os.path.basename(p)[:-3] + "."
            if os.path.isdir(cache):
                for c in os.listdir(cache):
                    if c.startswith(stem):
                        os.remove(cache + "/" + c)
                dirs.add(cache)
        try:
            os.remove(p)
        except OSError:
            pass
        dirs.add(os.path.dirname(p))
    for d in sorted(dirs, key=len, reverse=True):
        while d.startswith(SITE + "/") and d != SITE:
            try:
                os.rmdir(d)
            except OSError:
                break
            d = os.path.dirname(d)


def main(argv):
    global QUIET
    QUIET = False
    if not argv or argv[0] in ("-h", "--help", "help"):
        print(HELP)
        return 0
    if argv[0] in ("-V", "--version"):
        print("pip %s (kt, python %d.%d)" % (__import__("pip").__version__, PY[0], PY[1]))
        return 0
    cmd, args = argv[0], argv[1:]
    names, upgrade, deps, yes, index, files = [], False, True, False, INDEX, []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-U", "--upgrade"):
            upgrade = True
        elif a == "--no-deps":
            deps = False
        elif a in ("-y", "--yes"):
            yes = True
        elif a in ("-q", "--quiet"):
            QUIET = True
        elif a in ("-r", "--requirement"):
            i += 1
            files.append(args[i])
        elif a in ("-i", "--index-url"):
            i += 1
            index = args[i]
        elif a in ("--user", "--break-system-packages", "--no-cache-dir", "--disable-pip-version-check", "--no-warn-script-location") \
                or a.startswith("--root-user-action"):
            pass
        elif a.startswith("-"):
            raise Fail("неизвестный ключ %s (pip -h)" % a)
        else:
            names.append(a)
        i += 1
    for fn in files:
        with open(fn) as f:
            for line in f:
                line = line.split("#", 1)[0].strip()
                if line and not line.startswith("-"):
                    names.append(line)
    have = installed()
    if cmd == "install":
        if not names:
            raise Fail("что ставить? pip install пакет")
        Pip(index, upgrade, deps).install([requirement(n) for n in names])
    elif cmd == "uninstall":
        if not names:
            raise Fail("что удалять? pip uninstall пакет")
        for n in names:
            d = have.get(norm(requirement(n)[0]))
            if not d:
                say("%s не установлен" % n)
            elif not d["ours"]:
                r = repo_map().get(norm(d["name"]))
                raise Fail("%s %s установлен системой, удаляй через kt pkg rm %s" % (d["name"], d["version"], r["pkg"] if r else "<пакет>"))
            else:
                remove(d)
                say("удалён %s-%s" % (d["name"], d["version"]))
    elif cmd in ("list", "freeze"):
        for k in sorted(have):
            d = have[k]
            print(("%s==%s" if cmd == "freeze" else "%-24s %s") % (d["name"], d["version"]) + ("" if d["ours"] or cmd == "freeze" else "  (kt pkg)"))
    elif cmd == "show":
        for n in names:
            d = have.get(norm(n))
            if not d:
                raise Fail("%s не установлен" % n)
            print("Name: %s\nVersion: %s\nSummary: %s\nRequires: %s\nLocation: %s\nInstaller: %s" % (
                d["name"], d["version"], d.get("summary", ""), ", ".join(d["requires"]), SITE, "pip" if d["ours"] else "kt pkg"))
    else:
        raise Fail("неизвестная команда %s (pip -h)" % cmd)
    return 0


QUIET = False
if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except Fail as e:
        print("pip: " + str(e), file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        sys.exit(130)
